from pathlib import Path
from PIL import Image
import json,numpy as np
root=Path('tutorial/live2d-guidance/local-assets/hair-reference-templates')
m=json.loads((root/'manifest.json').read_text(encoding='utf8'))
for t in m['templates']:
    src={k:np.asarray(Image.open(v['path']).getchannel('A')) for k,v in t['sources'].items() if k.startswith('atlas')}
