        if l: crossing['left']=int(np.count_nonzero((a[top:b,l]>=64)&(a[top:b,l-1]>=64)))
        if r<w: crossing['right']=int(np.count_nonzero((a[top:b,r-1]>=64)&(a[top:b,r]>=64)))
        if top: crossing['top']=int(np.count_nonzero((a[top,l:r]>=64)&(a[top-1,l:r]>=64)))
        if b<h: crossing['bottom']=int(np.count_nonzero((a[b-1,l:r]>=64)&(a[b,l:r]>=64)))
        if any(crossing.values()):print(t['id'],p['title'],crossing)
